import { describe, it, expect } from 'vitest'
import { readFileSync, existsSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Task #675, AC5 and AC7: the clinic-facing procedure is a deliverable of this
 * task, so it is asserted like any other.
 *
 * Both assertions read the committed files as their data — nothing here is
 * generated by the test, so a passing run is a statement about what the clinic
 * actually reads. The step COUNT is asserted separately from the step CONTENT:
 * one assertion cannot both prove the four steps are present and prove there is
 * no fifth.
 */

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../../..')
const DOC = resolve(REPO_ROOT, 'docs/clinica/presupuestos-ejecutados-sin-cargo.md')
const CLAUDE_MD = resolve(REPO_ROOT, '.claude/CLAUDE.md')

describe('docs/clinica/presupuestos-ejecutados-sin-cargo.md (#675 AC5)', () => {
  it('exists', () => {
    expect(existsSync(DOC)).toBe(true)
  })

  const doc = () => readFileSync(DOC, 'utf8')

  // The ordered list of the procedure: markdown "1. " .. "4. " at line start.
  const stepLines = () =>
    doc()
      .split('\n')
      .filter((line) => /^\d+\. /.test(line))

  it('is written in Spanish', () => {
    const text = doc()
    // Spanish function words and accented forms the clinic's own prose carries.
    for (const marker of ['presupuesto', ' que ', ' el ', ' no ', 'línea', 'cita']) {
      expect(text).toContain(marker)
    }
    // Not an English draft that happens to keep the Spanish filename.
    for (const english of [' the ', ' budget ', ' appointment ']) {
      expect(text.toLowerCase()).not.toContain(english)
    }
  })

  it('carries exactly four numbered steps, numbered 1 to 4', () => {
    const steps = stepLines()
    expect(steps).toHaveLength(4)
    expect(steps.map((line) => line.match(/^(\d+)\. /)![1])).toEqual(['1', '2', '3', '4'])
  })

  it('step 1 sets the line back to Pendiente', () => {
    expect(stepLines()[0]).toMatch(/Pendiente/)
  })

  it('step 2 moves the budget from Borrador to Aprobado', () => {
    expect(stepLines()[1]).toMatch(/Borrador/)
    expect(stepLines()[1]).toMatch(/Aprobado/)
  })

  it('step 3 associates the line to the appointment', () => {
    expect(stepLines()[2]).toMatch(/cita/)
  })

  it('step 4 confirms the execution, which is what creates the charge', () => {
    expect(stepLines()[3]).toMatch(/ejecutó/)
    expect(stepLines()[3]).toMatch(/cargo/)
  })

  it('says the order is mandatory', () => {
    expect(doc()).toMatch(/el orden es obligatorio/i)
  })

  it('says Cancelado is not the step to take', () => {
    expect(doc()).toMatch(/Cancelado no es el paso/i)
  })

  it('warns that deleting and re-entering the record does not fix it and can strip correct charges', () => {
    const text = doc()
    expect(text).toMatch(/No borres/i)
    expect(text).toMatch(/no arregla nada/i)
    expect(text).toMatch(/cobros que ya estaban bien/i)
  })

  it('tells the clinic to reload rather than repeat a step when the displayed status disagrees', () => {
    const text = doc()
    expect(text).toMatch(/Recargá el\s+presupuesto/i)
    expect(text).toMatch(/No repitas el paso/i)
  })

  it('names no patient: the prose carries figures, dates and ids only', () => {
    // A single first-name + surname pair in body prose would be the leak; the
    // document is written entirely in the second person, so there is none.
    expect(doc()).not.toMatch(/paciente\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+/)
  })
})

describe('.claude/CLAUDE.md records the docs/clinica language exception (#675 AC7)', () => {
  const claudeMd = () => readFileSync(CLAUDE_MD, 'utf8')

  it('names docs/clinica/ as Spanish', () => {
    expect(claudeMd()).toMatch(/docs\/clinica\/[^\n]*\n?[^\n]*Spanish/)
  })

  it('states that every other deliverable follows deliverableLanguage', () => {
    expect(claudeMd()).toMatch(/deliverableLanguage/)
    expect(claudeMd()).toMatch(/English/)
  })
})
